def is_prime(number):
    if number <= 1:
        return False
    for i in range(2, number):
        if number % i == 0:
            return False
    return True

def main():
    data = sys.stdin.read().strip().split('\n')
    if not data:
        return
    first_line = data[0].strip()
    nums = list(map(int, first_line.split()))
    n, m = nums[0], nums[1]

    for i in range(n + 1, m + 1):
        if is_prime(i) and i != m:
            print("NO")
            return
        if is_prime(i):
            if i == m:
                print("YES")
                return
    print("NO")

if __name__ == "__main__":
    main()

